questionvariables.text:
correct_answer:rand_selection([
[1, true, "It is an assumption that some women are not fertile
."],
[2, true, "It is assumed that fertility is a deterministic  event, in that, every woman between the ages \\(15-49\\) years is not birth."],
[3, true, "There is an assumption that a woman can give birth to twins at any given  time
."]],1);

incorrect_answers:rand_selection([
[4, false, "Birth involves two parents who are of the opposite sex, estimation of fertility normally focuses on the mother while ignoring the father."],
[5, false, "There is an assumption that the mother gives birth to only one child at a time, multiple births is usually ignored."],
[6, false, "Demographers have not addressed polygamy in the estimation of fertility; it is normally assumed that one man normally has only one wife."],
[7, false, "Women  aging below \\(15\\) years or above \\(49\\) years are assumed not to be giving birth and ignored in the calculation of fertility.
"]], 3);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
